__NUXT_JSONP__("/por/how-to-apply/student-visa-f1", {data:[{details:{slug:"por",pageTitle:"Visto de Estudante F1 | Mentor Language Institute",pageDescription:"Por favor escolha uma opção da lista abaixo. Se você não tem certeza sobre a sua situação, clique em LEIA MAIS, para detalhes.",title:"Visto de Estudante F1",image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fvisa_application.jpg",subtitle:["Por favor escolha uma opção da lista abaixo. \u003Cbr \u002F\u003E Se você não tem certeza sobre a sua situação, clique em LEIA MAIS, para detalhes."],category:[{btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas_btn_por.png",link:"\u002Fpor\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas-students"},btn_transfer:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer_student_btn_por.png",link:"\u002Fpor\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students"},btn_status:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange_status_btn_por.png",link:"\u002Fpor\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status"}}],content:{subtitle:"Alguma dúvida?",description:["Normalmente, para que você fique por um período maior nos Estados Unidos, você vai precisar de um visto de estudante.","Se você não tem certeza se precisa ou não de um visto, sinta-se a vontade de entrar em contato conosco.","Nós temos um time de funcionários com capacidade de comunicação em 8 línguas diferentes."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-por.jpg",link:"\u002Fpor\u002Fcontact"}},dir:"\u002Fstudent-visa-f1",path:"\u002Fstudent-visa-f1\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:31.130Z",updatedAt:"2025-05-26T12:06:27.925Z"}}],fetch:{},mutations:void 0});